39	
40	builder.Services.AddOptions<GoogleAuthOptions>()
41	    .Bind(builder.Configuration.GetSection(GoogleAuthOptions.SectionName))
42	    .ValidateDataAnnotations()
43	    .ValidateOnStart();
44	
45	builder.Services.AddOptions<SeedOptions>()
46	    .Bind(builder.Configuration.GetSection(SeedOptions.SectionName))
47	    .ValidateDataAnnotations()
48	    .ValidateOnStart();
49	
50	builder.Services.AddOptions<CorsOptions>()
51	    .Bind(builder.Configuration.GetSection(CorsOptions.SectionName))
52	    .ValidateDataAnnotations()
53	    .ValidateOnStart();
54	
55	builder.Services.AddOptions<ConnectionStringOptions>()
56	    .Bind(builder.Configuration.GetSection(ConnectionStringOptions.SectionName))
57	    .ValidateDataAnnotations()
58	    .ValidateOnStart();
59	
60	builder.Services.AddOptions<RateLimitOptions>()
61	    .Bind(builder.Configuration.GetSection(RateLimitOptions.SectionName))
62	    .ValidateDataAnnotations()
63	    .ValidateOnStart();
64	
65	// ── Database ──────────────────────────────────────────────────────────────────
66	
67	DapperConfiguration.RegisterTypeHandlers();
68	
69	// Resolve the connection string lazily from IOptions so that WebApplicationFactory
70	// configuration overrides (applied after builder services are registered) are honoured.
71	builder.Services.AddScoped<IDbConnection>(sp =>
72	{
73	    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
74	    var conn = new SqliteConnection(opts.Kanban);
75	    conn.Open();
76	    using var cmd = conn.CreateCommand();
77	    cmd.CommandText = "PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;";
78	    cmd.ExecuteNonQuery();
79	    return conn;
80	});
81	
82	// ── Exception Handling ────────────────────────────────────────────────────────
83	
84	builder.Services.AddProblemDetails(options =>
85	{
86	    options.CustomizeProblemDetails = ctx =>
87	    {
88	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
89	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
90	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
91	        {
92	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
93	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
94	        }
95	    };
96	});
97	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
98	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
99	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
100	
101	// ── CORS ──────────────────────────────────────────────────────────────────────
102	
103	builder.Services.AddCors(options =>
104	    options.AddPolicy("KanbanWebApp", policy =>
105	        policy
106	            .WithOrigins(
107	                builder.Configuration
108	                    .GetSection("Cors:AllowedOrigins")
109	                    .Get<string[]>() ?? [])
110	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
111	            .AllowAnyHeader()
112	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
113	
114	// ── Authentication & Authorization ───────────────────────────────────────────
115	
116	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
117	builder.Services.AddScoped<IAuthService, AuthService>();
118	builder.Services.AddScoped<IInvitationService, InvitationService>();
119	builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
120	builder.Services.AddScoped<GoogleIdentityAdapter>();
121	builder.Services.AddScoped<IUserRepository, UserRepository>();
122	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
123	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
124	builder.Services.AddScoped<IBoardRepository, BoardRepository>();
125	builder.Services.AddScoped<ILaneRepository, LaneRepository>();
126	builder.Services.AddScoped<ICardRepository, CardRepository>();
127	builder.Services.AddScoped<IBoardMemberRepository, BoardMemberRepository>();
128	builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
129	builder.Services.AddHttpContextAccessor();
130	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
131	builder.Services.AddScoped<IAuthorizationHandler, BoardAuthorizationHandler>();
132	builder.Services.AddScoped<IBoardService, BoardService>();
133	builder.Services.AddScoped<ILaneService, LaneService>();
134	builder.Services.AddScoped<ICardService, CardService>();
135	builder.Services.AddScoped<IBoardMembershipService, BoardMembershipService>();
136	
137	builder.Services.AddAuthentication(options =>
138	    {
139	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
140	        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
141	    })
142	    .AddCookie(options =>
143	    {
144	        options.LoginPath = "/api/v1/auth/signin";
145	        options.Events.OnRedirectToLogin = ctx =>
146	        {
147	            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
148	            return Task.CompletedTask;
149	        };
150	        options.Events.OnRedirectToAccessDenied = ctx =>
151	        {
152	            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
153	            return Task.CompletedTask;
154	        };
155	    })
156	    .AddGoogle(options =>
157	    {
158	        var googleOpts = builder.Configuration
159	            .GetSection(GoogleAuthOptions.SectionName)
160	            .Get<GoogleAuthOptions>()!;
161	        options.ClientId = googleOpts.ClientId;
162	        options.ClientSecret = googleOpts.ClientSecret;
163	
164	        // ASP.NET Core's default ClaimActions remap "sub" → ClaimTypes.NameIdentifier
165	        // (a long URN). GoogleIdentityAdapter expects the raw OIDC claim names, so we
166	        // clear the defaults and map only the three fields the adapter actually reads.
167	        options.ClaimActions.Clear();
168	        options.ClaimActions.MapJsonKey("sub", "sub");
169	        options.ClaimActions.MapJsonKey("email", "email");
170	        options.ClaimActions.MapJsonKey("name", "name");
171	
172	        options.Events.OnTicketReceived = async ctx =>
173	        {
174	            var adapter = ctx.HttpContext.RequestServices
175	                .GetRequiredService<GoogleIdentityAdapter>();
176	            var authService = ctx.HttpContext.RequestServices
177	                .GetRequiredService<IAuthService>();
178	
179	            if (ctx.Principal is not null)
180	            {
181	                var identity = adapter.Extract(ctx.Principal);
182	                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
183	                if (claimsIdentity is not null)
184	                {
185	                    await authService.HandleSignInAsync(
186	                        identity.Sub,
187	                        identity.Email,
188	                        claimsIdentity,
189	                        ctx.HttpContext.RequestAborted);
190	                }
191	            }
192	        };
193	    });
194	
195	builder.Services.AddAuthorizationBuilder()
196	    .AddPolicy("RegisteredUser", policy => policy
197	        .RequireAuthenticatedUser()
198	        .AddRequirements(new RegisteredUserRequirement()))
199	    .AddPolicy("Admin", policy => policy
200	        .RequireAuthenticatedUser()
201	        .RequireClaim("system_role", "admin"));
202	
203	// ── API Versioning ────────────────────────────────────────────────────────────
204	
205	builder.Services.AddApiVersioning(options =>
206	{
207	    options.DefaultApiVersion = new ApiVersion(1, 0);
208	    options.AssumeDefaultVersionWhenUnspecified = true;
209	    options.ReportApiVersions = true;
210	});
211	
212	// ── OpenAPI — development only ────────────────────────────────────────────────
213	
214	if (builder.Environment.IsDevelopment())
215	    builder.Services.AddOpenApi();
216	
217	// ── Health Checks ─────────────────────────────────────────────────────────────
218	
219	builder.Services.AddHealthChecks()
220	    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
221	    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);
222	
223	// ── Rate Limiting ─────────────────────────────────────────────────────────────
224	
225	builder.Services.AddRateLimiter(opts =>
226	{
227	    var rateLimits = builder.Configuration
228	        .GetSection(RateLimitOptions.SectionName)
229	        .Get<RateLimitOptions>() ?? new RateLimitOptions();
230	
231	    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
232	    opts.OnRejected = async (ctx, _) =>
233	    {
234	        ctx.HttpContext.Response.Headers.RetryAfter = "60";
235	        await Results.Problem(
236	                title: "Too many requests",
237	                statusCode: StatusCodes.Status429TooManyRequests,
238	                detail: "Please retry after the Retry-After interval.")
239	            .ExecuteAsync(ctx.HttpContext);
240	    };
241	
242	    opts.AddPolicy("anonymous", httpContext =>
243	        RateLimitPartition.GetFixedWindowLimiter(
244	            partitionKey: httpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown",
245	            factory: _ => new System.Threading.RateLimiting.FixedWindowRateLimiterOptions
246	            {
247	                PermitLimit = rateLimits.AnonymousPermitLimit,
248	                Window = TimeSpan.FromMinutes(1),
249	            }));
250	
251	    opts.AddPolicy("authenticated", httpContext =>
252	    {
253	        var userId = httpContext.User.FindFirst("sub")?.Value
254	            ?? httpContext.Connection.RemoteIpAddress?.ToString()
255	            ?? "anonymous";
256	        return RateLimitPartition.GetSlidingWindowLimiter(userId, _ => new SlidingWindowRateLimiterOptions
257	        {
258	            PermitLimit = rateLimits.AuthenticatedPermitLimit,
259	            Window = TimeSpan.FromMinutes(1),
260	            SegmentsPerWindow = 6,
261	        });
262	    });
263	
264	    opts.AddPolicy("mutating", httpContext =>
265	    {
266	        var userId = httpContext.User.FindFirst("sub")?.Value
267	            ?? httpContext.Connection.RemoteIpAddress?.ToString()
268	            ?? "anonymous";
269	        return RateLimitPartition.GetSlidingWindowLimiter(userId, _ => new SlidingWindowRateLimiterOptions
270	        {
271	            PermitLimit = rateLimits.MutatingPermitLimit,
272	            Window = TimeSpan.FromMinutes(1),
273	            SegmentsPerWindow = 6,
274	        });
275	    });
276	});
277	
278	// ── Build ─────────────────────────────────────────────────────────────────────
279	
280	var app = builder.Build();
281	
282	// ── Migrations ────────────────────────────────────────────────────────────────
283	
284	// Read connection string post-build so WebApplicationFactory test overrides are resolved.
285	var connectionString = app.Configuration.GetConnectionString("Kanban")
286	    ?? throw new InvalidOperationException("ConnectionStrings:Kanban is required.");
287	
288	var seedOptions = app.Services.GetRequiredService<IOptions<SeedOptions>>().Value;
289	var migrationsAssembly = AppDomain.CurrentDomain.GetAssemblies()
290	    .FirstOrDefault(a => a.GetName().Name == "Kanban.Data")
291	    ?? Assembly.Load("Kanban.Data");
292	
293	var upgradeResult = DeployChanges.To
294	    .SqliteDatabase(connectionString)
295	    .WithScriptsEmbeddedInAssembly(
296	        migrationsAssembly,
297	        name => name.Contains("sqlite", StringComparison.OrdinalIgnoreCase))
298	    .WithVariables(new Dictionary<string, string>
299	    {
300	        ["AdminEmail"] = seedOptions.AdminEmail,
301	        ["AdminUserId"] = Guid.NewGuid().ToString("D"),
302	        ["SeedTimestamp"] = DateTimeOffset.UtcNow.ToString("o"),
303	    })
304	    .LogToConsole()
305	    .Build()
306	    .PerformUpgrade();
307	
308	if (!upgradeResult.Successful)
309	    throw new InvalidOperationException($"Database migration failed: {upgradeResult.Error?.Message}");
310	
311	// ── Middleware pipeline ───────────────────────────────────────────────────────
312	// Order matters — see constitution Security Headers and Containerization sections.
313	
314	app.UseForwardedHeaders(new ForwardedHeadersOptions
315	{
316	    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto
317	});
318	
319	if (!app.Environment.IsDevelopment())
320	    app.UseHttpsRedirection();
321	
322	app.Use(async (ctx, next) =>
323	{
324	    var correlationId = ctx.Request.Headers["X-Correlation-Id"].FirstOrDefault()
325	                        ?? Activity.Current?.Id
326	                        ?? Guid.NewGuid().ToString("N");
327	    Activity.Current?.SetTag("correlation.id", correlationId);
328	    ctx.Response.Headers["X-Correlation-Id"] = correlationId;
329	    await next();
330	});
331	
332	app.UseSecurityHeaders(policies =>
333	    policies
334	        .AddDefaultSecurityHeaders()
335	        .AddStrictTransportSecurityMaxAgeIncludeSubDomains(maxAgeInSeconds: 60 * 60 * 24 * 365)
336	        .AddContentSecurityPolicy(csp =>
337	        {
338	            csp.AddDefaultSrc().Self();
339	            csp.AddScriptSrc().Self();
340	            csp.AddStyleSrc().Self().UnsafeInline();
341	            csp.AddImgSrc().Self().Data().From("https://lh3.googleusercontent.com");
342	            csp.AddConnectSrc().Self();
343	            csp.AddFrameAncestors().None();
344	            csp.AddFormAction().Self().From("https://accounts.google.com");
345	        })
346	        .AddPermissionsPolicy(permissions =>
347	        {
348	            permissions.AddAccelerometer().None();
349	            permissions.AddCamera().None();
350	            permissions.AddGeolocation().None();
351	            permissions.AddMicrophone().None();
352	            permissions.AddPayment().None();
353	            permissions.AddUsb().None();
354	        }));
355	
356	app.UseExceptionHandler();
357	app.UseStatusCodePages();
358	
359	app.UseRouting();
360	app.UseCors("KanbanWebApp");
361	app.UseAuthentication();
362	app.UseAuthorization();
363	app.UseRateLimiter();
364	
365	// ── Health endpoints — public, excluded from auth group ───────────────────────
366	
367	app.MapHealthChecks("/health/live", new HealthCheckOptions
368	{
369	    Predicate = check => check.Tags.Contains("live")
370	});
371	
372	app.MapHealthChecks("/health/ready", new HealthCheckOptions
373	{
374	    Predicate = check => check.Tags.Contains("ready")
375	});
376	
377	// ── OpenAPI — development only ────────────────────────────────────────────────
378	
379	if (app.Environment.IsDevelopment())
380	{
381	    app.MapOpenApi();
382	    app.MapScalarApiReference();
383	
384	    var devGroup = app.MapGroup("/api/v1").AllowAnonymous();
385	    DevEndpoints.Map(devGroup);
386	}
387	
388	// ── Versioned API (v1) — endpoints registered in Endpoints/ ───────────────────
389	
390	var v1 = app.NewVersionedApi();
391	var v1RegisteredUserGroup = v1.MapGroup("/api/v1")
392	    .HasApiVersion(1, 0)
393	    .RequireAuthorization("RegisteredUser");
394	AuthEndpoints.Map(v1RegisteredUserGroup);
395	InviteEndpoints.Map(v1RegisteredUserGroup);
396	BoardEndpoints.Map(v1RegisteredUserGroup);
397	LaneEndpoints.Map(v1RegisteredUserGroup);
398	CardEndpoints.Map(v1RegisteredUserGroup);
399	BoardMemberEndpoints.Map(v1RegisteredUserGroup);
400	
401	var v1GoogleAuthGroup = v1.MapGroup("/api/v1")
402	    .HasApiVersion(1, 0)
403	    .RequireAuthorization();
404	InviteEndpoints.MapAcceptEndpoint(v1GoogleAuthGroup);
405	
406	app.Run();
407	
408	public partial class Program { }
