// ── Database ──────────────────────────────────────────────────────────────────

DapperConfiguration.RegisterTypeHandlers();

// Resolve the connection string lazily from IOptions so that WebApplicationFactory
// configuration overrides (applied after builder services are registered) are honoured.
builder.Services.AddScoped<IDbConnection>(sp =>
{
    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
    var conn = new SqliteConnection(opts.Kanban);
    conn.Open();
    using var cmd = conn.CreateCommand();
    cmd.CommandText = "PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;";
    cmd.ExecuteNonQuery();
    return conn;
});

// ── Exception Handling ────────────────────────────────────────────────────────

builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = ctx =>
    {
        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
        {
            ctx.ProblemDetails.Title = "You are not registered to use this application.";
            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
        }
    };
});
builder.Services.AddExceptionHandler<DomainExceptionHandler>();
builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
builder.Services.AddExceptionHandler<FallbackExceptionHandler>();

// ── CORS ──────────────────────────────────────────────────────────────────────

builder.Services.AddCors(options =>
    options.AddPolicy("KanbanWebApp", policy =>
        policy
            .WithOrigins(
                builder.Configuration
                    .GetSection("Cors:AllowedOrigins")
                    .Get<string[]>() ?? [])
            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
            .AllowAnyHeader()
            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));

// ── Authentication & Authorization ───────────────────────────────────────────

builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
builder.Services.AddScoped<IAuthService, AuthService>();
builder.Services.AddScoped<IInvitationService, InvitationService>();
builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
builder.Services.AddScoped<GoogleIdentityAdapter>();
builder.Services.AddScoped<IUserRepository, UserRepository>();
builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
builder.Services.AddScoped<IBoardRepository, BoardRepository>();
builder.Services.AddScoped<ILaneRepository, LaneRepository>();
builder.Services.AddScoped<ICardRepository, CardRepository>();
builder.Services.AddScoped<IBoardMemberRepository, BoardMemberRepository>();
builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
builder.Services.AddHttpContextAccessor();
builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
builder.Services.AddScoped<IAuthorizationHandler, BoardAuthorizationHandler>();
builder.Services.AddScoped<IBoardService, BoardService>();
builder.Services.AddScoped<ILaneService, LaneService>();
builder.Services.AddScoped<ICardService, CardService>();
builder.Services.AddScoped<IBoardMembershipService, BoardMembershipService>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
        options.DefaultChallengeScheme = GoogleDefaults.AuthenticationScheme;
    })
    .AddCookie(options =>
    {
        options.LoginPath = "/api/v1/auth/signin";
        options.Events.OnRedirectToLogin = ctx =>
        {
            ctx.Response.StatusCode = StatusCodes.Status401Unauthorized;
            return Task.CompletedTask;
        };
        options.Events.OnRedirectToAccessDenied = ctx =>
        {
            ctx.Response.StatusCode = StatusCodes.Status403Forbidden;
            return Task.CompletedTask;
        };
    })
    .AddGoogle(options =>
    {
        var googleOpts = builder.Configuration
            .GetSection(GoogleAuthOptions.SectionName)
            .Get<GoogleAuthOptions>()!;
        options.ClientId = googleOpts.ClientId;
        options.ClientSecret = googleOpts.ClientSecret;

        // ASP.NET Core's default ClaimActions remap "sub" → ClaimTypes.NameIdentifier
        // (a long URN). GoogleIdentityAdapter expects the raw OIDC claim names, so we
        // clear the defaults and map only the three fields the adapter actually reads.
        options.ClaimActions.Clear();
        options.ClaimActions.MapJsonKey("sub", "sub");
        options.ClaimActions.MapJsonKey("email", "email");
        options.ClaimActions.MapJsonKey("name", "name");

        options.Events.OnTicketReceived = async ctx =>
        {
            var adapter = ctx.HttpContext.RequestServices
                .GetRequiredService<GoogleIdentityAdapter>();
            var authService = ctx.HttpContext.RequestServices
                .GetRequiredService<IAuthService>();

            if (ctx.Principal is not null)
            {
                var identity = adapter.Extract(ctx.Principal);
                var claimsIdentity = ctx.Principal.Identity as System.Security.Claims.ClaimsIdentity;
                if (claimsIdentity is not null)
                {
                    await authService.HandleSignInAsync(
                        identity.Sub,
                        identity.Email,
                        claimsIdentity,
                        ctx.HttpContext.RequestAborted);
                }
            }
        };
    });

builder.Services.AddAuthorizationBuilder()
    .AddPolicy("RegisteredUser", policy => policy
        .RequireAuthenticatedUser()
        .AddRequirements(new RegisteredUserRequirement()))
    .AddPolicy("Admin", policy => policy
        .RequireAuthenticatedUser()
        .RequireClaim("system_role", "admin"));

// ── API Versioning ────────────────────────────────────────────────────────────

builder.Services.AddApiVersioning(options =>
{
    options.DefaultApiVersion = new ApiVersion(1, 0);
    options.AssumeDefaultVersionWhenUnspecified = true;
    options.ReportApiVersions = true;
});

// ── OpenAPI — development only ────────────────────────────────────────────────

if (builder.Environment.IsDevelopment())
    builder.Services.AddOpenApi();

// ── Health Checks ─────────────────────────────────────────────────────────────

builder.Services.AddHealthChecks()
    .AddCheck("self", () => Microsoft.Extensions.Diagnostics.HealthChecks.HealthCheckResult.Healthy(), tags: ["live"])
    .AddCheck<DatabaseHealthCheck>("database", tags: ["ready"]);

// ── Rate Limiting ─────────────────────────────────────────────────────────────

builder.Services.AddRateLimiter(opts =>
{
    var rateLimits = builder.Configuration
        .GetSection(RateLimitOptions.SectionName)
        .Get<RateLimitOptions>() ?? new RateLimitOptions();

    opts.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    opts.OnRejected = async (ctx, _) =>
    {
        ctx.HttpContext.Response.Headers.RetryAfter = "60";
        await Results.Problem(
                title: "Too many requests",
                statusCode: StatusCodes.Status429TooManyRequests,
                detail: "Please retry after the Retry-After interval.")
            .ExecuteAsync(ctx.HttpContext);
    };

    opts.AddPolicy("anonymous", httpContext =>
        RateLimitPartition.GetFixedWindowLimiter(
            partitionKey: httpContext.Connection.RemoteIpAddress?.ToString() ?? "unknown",
            factory: _ => new System.Threading.RateLimiting.FixedWindowRateLimiterOptions
            {
                PermitLimit = rateLimits.AnonymousPermitLimit,
                Window = TimeSpan.FromMinutes(1),
            }));

    opts.AddPolicy("authenticated", httpContext =>
    {
        var userId = httpContext.User.FindFirst("sub")?.Value
            ?? httpContext.Connection.RemoteIpAddress?.ToString()
            ?? "anonymous";
        return RateLimitPartition.GetSlidingWindowLimiter(userId, _ => new SlidingWindowRateLimiterOptions
        {
            PermitLimit = rateLimits.AuthenticatedPermitLimit,
            Window = TimeSpan.FromMinutes(1),
            SegmentsPerWindow = 6,
        });
    });

    opts.AddPolicy("mutating", httpContext =>
    {
        var userId = httpContext.User.FindFirst("sub")?.Value
            ?? httpContext.Connection.RemoteIpAddress?.ToString()
            ?? "anonymous";
        return RateLimitPartition.GetSlidingWindowLimiter(userId, _ => new SlidingWindowRateLimiterOptions
        {
            PermitLimit = rateLimits.MutatingPermitLimit,
            Window = TimeSpan.FromMinutes(1),
            SegmentsPerWindow = 6,
        });
    });
});

// ── Build ─────────────────────────────────────────────────────────────────────

var app = builder.Build();

// ── Migrations ────────────────────────────────────────────────────────────────

// Read connection string post-build so WebApplicationFactory test overrides are resolved.
var connectionString = app.Configuration.GetConnectionString("Kanban")
    ?? throw new InvalidOperationException("ConnectionStrings:Kanban is required.");

var seedOptions = app.Services.GetRequiredService<IOptions<SeedOptions>>().Value;
var migrationsAssembly = AppDomain.CurrentDomain.GetAssemblies()
    .FirstOrDefault(a => a.GetName().Name == "Kanban.Data")
    ?? Assembly.Load("Kanban.Data");

var upgradeResult = DeployChanges.To
    .SqliteDatabase(connectionString)
    .WithScriptsEmbeddedInAssembly(
        migrationsAssembly,
        name => name.Contains("sqlite", StringComparison.OrdinalIgnoreCase))
    .WithVariables(new Dictionary<string, string>
    {
        ["AdminEmail"] = seedOptions.AdminEmail,
        ["AdminUserId"] = Guid.NewGuid().ToString("D"),
        ["SeedTimestamp"] = DateTimeOffset.UtcNow.ToString("o"),
    })
    .LogToConsole()
    .Build()
    .PerformUpgrade();

if (!upgradeResult.Successful)
    throw new InvalidOperationException($"Database migration failed: {upgradeResult.Error?.Message}");

// ── Middleware pipeline ───────────────────────────────────────────────────────
// Order matters — see constitution Security Headers and Containerization sections.

app.UseForwardedHeaders(new ForwardedHeadersOptions
{
    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto
});

if (!app.Environment.IsDevelopment())
    app.UseHttpsRedirection();

app.Use(async (ctx, next) =>
{
    var correlationId = ctx.Request.Headers["X-Correlation-Id"].FirstOrDefault()
                        ?? Activity.Current?.Id
                        ?? Guid.NewGuid().ToString("N");
    Activity.Current?.SetTag("correlation.id", correlationId);
    ctx.Response.Headers["X-Correlation-Id"] = correlationId;
    await next();
});

app.UseSecurityHeaders(policies =>
    policies
        .AddDefaultSecurityHeaders()
        .AddStrictTransportSecurityMaxAgeIncludeSubDomains(maxAgeInSeconds: 60 * 60 * 24 * 365)
        .AddContentSecurityPolicy(csp =>
        {
            csp.AddDefaultSrc().Self();
            csp.AddScriptSrc().Self();
            csp.AddStyleSrc().Self().UnsafeInline();
            csp.AddImgSrc().Self().Data().From("https://lh3.googleusercontent.com");
            csp.AddConnectSrc().Self();
            csp.AddFrameAncestors().None();
            csp.AddFormAction().Self().From("https://accounts.google.com");
        })
        .AddPermissionsPolicy(permissions =>
        {
            permissions.AddAccelerometer().None();
            permissions.AddCamera().None();
            permissions.AddGeolocation().None();
            permissions.AddMicrophone().None();
            permissions.AddPayment().None();
            permissions.AddUsb().None();
        }));

app.UseExceptionHandler();
app.UseStatusCodePages();

app.UseRouting();
app.UseCors("KanbanWebApp");
app.UseAuthentication();
app.UseAuthorization();
app.UseRateLimiter();

// ── Health endpoints — public, excluded from auth group ───────────────────────

app.MapHealthChecks("/health/live", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("live")
});

app.MapHealthChecks("/health/ready", new HealthCheckOptions
{
    Predicate = check => check.Tags.Contains("ready")
});

// ── OpenAPI — development only ────────────────────────────────────────────────

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
    app.MapScalarApiReference();

    var devGroup = app.MapGroup("/api/v1").AllowAnonymous();
    DevEndpoints.Map(devGroup);
}

// ── Versioned API (v1) — endpoints registered in Endpoints/ ───────────────────

var v1 = app.NewVersionedApi();
var v1RegisteredUserGroup = v1.MapGroup("/api/v1")
    .HasApiVersion(1, 0)
    .RequireAuthorization("RegisteredUser");
AuthEndpoints.Map(v1RegisteredUserGroup);
InviteEndpoints.Map(v1RegisteredUserGroup);
BoardEndpoints.Map(v1RegisteredUserGroup);
LaneEndpoints.Map(v1RegisteredUserGroup);
CardEndpoints.Map(v1RegisteredUserGroup);
BoardMemberEndpoints.Map(v1RegisteredUserGroup);

var v1GoogleAuthGroup = v1.MapGroup("/api/v1")
    .HasApiVersion(1, 0)
    .RequireAuthorization();
InviteEndpoints.MapAcceptEndpoint(v1GoogleAuthGroup);

app.Run();

public partial class Program { }

using System.Data;
using FluentValidation;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Exceptions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class BoardMembershipService : IBoardMembershipService
{
    private readonly IBoardMemberRepository _boardMemberRepository;
    private readonly IInvitationService _invitationService;
    private readonly IUserRepository _userRepository;
    private readonly ICurrentUserService _currentUserService;
    private readonly IAuthorizationService _authorizationService;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<BoardMembershipService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public BoardMembershipService(
        IBoardMemberRepository boardMemberRepository,
        IInvitationService invitationService,
        IUserRepository userRepository,
        ICurrentUserService currentUserService,
        IAuthorizationService authorizationService,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<BoardMembershipService> logger)
    {
        ArgumentNullException.ThrowIfNull(boardMemberRepository);
        ArgumentNullException.ThrowIfNull(invitationService);
        ArgumentNullException.ThrowIfNull(userRepository);
        ArgumentNullException.ThrowIfNull(currentUserService);
        ArgumentNullException.ThrowIfNull(authorizationService);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _boardMemberRepository = boardMemberRepository;
        _invitationService = invitationService;
        _userRepository = userRepository;
        _currentUserService = currentUserService;
        _authorizationService = authorizationService;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<IReadOnlyList<BoardMemberDto>> ListMembersAsync(Guid boardId)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);

        var callerId = _currentUserService.UserId!.Value;
        var callerRole = await _boardMemberRepository.FindRoleAsync(boardId, callerId) ?? throw new NotFoundException("board.not_found", "Board not found.");
        var members = await _boardMemberRepository.FindAllForBoardAsync(boardId);

        var userIds = members.Select(m => m.UserId).ToList();
        var users = await _userRepository.FindByIdsAsync(userIds);
        var userMap = users.ToDictionary(u => u.Id, u => u.DisplayName);

        return members
            .OrderBy(m => m.JoinedAt)
            .Select(m => BoardMemberTransforms.ToDto(m, userMap.GetValueOrDefault(m.UserId, m.UserId.ToString())))
            .ToList();
    }

    public async Task InviteAsync(Guid boardId, InviteBoardMemberRequest request, string frontendBaseUrl)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        ArgumentNullException.ThrowIfNull(request);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("frontendBaseUrl") }
            .ValidateAndThrow(frontendBaseUrl);

        var callerId = _currentUserService.UserId!.Value;
        var callerRole = await _boardMemberRepository.FindRoleAsync(boardId, callerId) ?? throw new NotFoundException("board.not_found", "Board not found.");
        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.ManageMembers));
        if (!auth.Succeeded)
            throw new ForbiddenException("member.forbidden", "Only board owners can invite members.");

        var callerSystemRole = _currentUserService.SystemRole == "admin"
            ? SystemRole.Admin
            : SystemRole.Standard;

        var existingUser = await _userRepository.FindByEmailAsync(request.Email);
        if (existingUser is not null)
        {
            var existingRole = await _boardMemberRepository.FindRoleAsync(boardId, existingUser.Id);
            if (existingRole is not null)
                throw new ConflictException("member.already_member", "This user is already a member of the board.");

            var boardRole = ToDomainRole(request.Role);
            await RetryPolicy.ExecuteAsync(async _ =>
            {
                using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
                try
                {
                    var member = new BoardMember(
                        id: Guid.NewGuid(),
                        boardId: boardId,
                        userId: existingUser.Id,
                        role: boardRole,
                        invitedByUserId: callerId,
                        joinedAt: DateTimeOffset.UtcNow);
                    await _boardMemberRepository.InsertAsync(member, tx);
                    tx.Commit();
                    _logger.LogInformation(
                        "Existing user {UserId} added to board {BoardId} with role {Role} by {CallerId}",
                        existingUser.Id, boardId, boardRole, callerId);
                }
                catch
                {
                    tx.Rollback();
                    throw;
                }
            }, CancellationToken.None);
            return;
        }

        var (inviteResponse, _) = await _invitationService.IssueAsync(
            request.Email,
            callerId,
            callerSystemRole,
            frontendBaseUrl,
            boardId: boardId,
            boardRole: ToDomainRole(request.Role));

        _logger.LogInformation(
            "Board invite {InvitationId} issued to board {BoardId} by {CallerId}",
            inviteResponse.InvitationId, boardId, callerId);
    }

    public async Task<BoardMemberDto> ChangeRoleAsync(Guid boardId, Guid userId, ChangeMemberRoleRequest request)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("userId") }
            .ValidateAndThrow(userId);
        ArgumentNullException.ThrowIfNull(request);

        var callerId = _currentUserService.UserId!.Value;
        var callerRole = await _boardMemberRepository.FindRoleAsync(boardId, callerId) ?? throw new NotFoundException("board.not_found", "Board not found.");
        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.ManageMembers));
        if (!auth.Succeeded)
            throw new ForbiddenException("member.forbidden", "Only board owners can change member roles.");

        var preflightTargetRole = await _boardMemberRepository.FindRoleAsync(boardId, userId) ?? throw new NotFoundException("member.not_found", "Target user is not a member of this board.");
        var newRole = ToDomainRole(request.Role);

        return await RetryPolicy.ExecuteAsync(async _ =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var currentTargetRole = await _boardMemberRepository.FindRoleAsync(boardId, userId, tx);
                if (newRole != BoardRole.Owner && currentTargetRole == BoardRole.Owner)
                {
                    var ownerCount = await _boardMemberRepository.CountOwnersAsync(boardId, tx);
                    if (ownerCount <= 1)
                        throw new BusinessRuleException("member.last_owner", "Cannot remove the last owner from the board.");
                }

                await _boardMemberRepository.UpdateRoleAsync(boardId, userId, newRole, tx);

                var members = await _boardMemberRepository.FindAllForBoardAsync(boardId, tx);
                var updated = members.FirstOrDefault(m => m.UserId == userId)
                    ?? throw new NotFoundException("member.not_found", "Target user is not a member of this board.");
                var user = await _userRepository.FindByIdAsync(userId, tx);
                var displayName = user?.DisplayName ?? userId.ToString();

                tx.Commit();
                _logger.LogInformation(
                    "Member {UserId} role changed to {Role} on board {BoardId} by {CallerId}",
                    userId, newRole, boardId, callerId);
                return BoardMemberTransforms.ToDto(updated, displayName);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, CancellationToken.None);
    }

    public async Task RemoveMemberAsync(Guid boardId, Guid userId)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("userId") }
            .ValidateAndThrow(userId);

        var callerId = _currentUserService.UserId!.Value;
        var callerRole = await _boardMemberRepository.FindRoleAsync(boardId, callerId) ?? throw new NotFoundException("board.not_found", "Board not found.");
        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal,
            new BoardContext(boardId),
            new BoardMembershipRequirement(BoardOperations.ManageMembers));
        if (!auth.Succeeded)
            throw new ForbiddenException("member.forbidden", "Only board owners can remove members.");

        var preflightTargetRole = await _boardMemberRepository.FindRoleAsync(boardId, userId) ?? throw new NotFoundException("member.not_found", "Target user is not a member of this board.");
        await RetryPolicy.ExecuteAsync(async _ =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var currentTargetRole = await _boardMemberRepository.FindRoleAsync(boardId, userId, tx);
                if (currentTargetRole == BoardRole.Owner)
                {
                    var ownerCount = await _boardMemberRepository.CountOwnersAsync(boardId, tx);
                    if (ownerCount <= 1)
                        throw new BusinessRuleException("member.last_owner", "Cannot remove the last owner from the board.");
                }

                await _boardMemberRepository.DeleteAsync(boardId, userId, tx);
                tx.Commit();
                _logger.LogInformation(
                    "Member {UserId} removed from board {BoardId} by {CallerId}", userId, boardId, callerId);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, CancellationToken.None);
    }

    private static BoardRole ToDomainRole(BoardRoleDto dto) => dto switch
    {
        BoardRoleDto.Owner  => BoardRole.Owner,
        BoardRoleDto.Member => BoardRole.Member,
        BoardRoleDto.Viewer => BoardRole.Viewer,
        _                   => throw new ArgumentOutOfRangeException(nameof(dto)),
    };
}

import { useState } from 'react'
import {
  Button,
  Field,
  Input,
  MessageBar,
  MessageBarBody,
  Select,
  Spinner,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useBoardMembers, type BoardMember } from '../../hooks/useBoardMembers'
import { useInviteBoardMember } from '../../hooks/useInviteBoardMember'
import { useChangeMemberRole } from '../../hooks/useChangeMemberRole'
import { useRemoveBoardMember } from '../../hooks/useRemoveBoardMember'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalM,
    minWidth: '320px',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: tokens.spacingVerticalM,
  },
  list: {
    listStyle: 'none',
    padding: 0,
    margin: 0,
  },
  item: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: tokens.spacingHorizontalS,
    padding: `${tokens.spacingVerticalS} 0`,
    borderBottom: `1px solid ${tokens.colorNeutralStroke2}`,
  },
  name: {
    flexGrow: 1,
  },
  inviteForm: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
    marginBottom: tokens.spacingVerticalM,
  },
  inviteRow: {
    display: 'flex',
    gap: tokens.spacingHorizontalS,
  },
})

type BoardRole = 'Owner' | 'Member' | 'Viewer'

interface BoardMembersPanelProps {
  boardId: string
  callerRole: BoardRole
}

export default function BoardMembersPanel({ boardId, callerRole }: BoardMembersPanelProps) {
  const styles = useStyles()
  const [inviteOpen, setInviteOpen] = useState(false)
  const [inviteEmail, setInviteEmail] = useState('')
  const [inviteRole, setInviteRole] = useState<BoardRole>('Member')
  const [inviteSuccess, setInviteSuccess] = useState(false)

  const { data: members, isPending } = useBoardMembers(boardId)
  const inviteMutation = useInviteBoardMember()
  const changeRoleMutation = useChangeMemberRole()
  const removeMutation = useRemoveBoardMember()

  const isOwner = callerRole === 'Owner'
  const ownerCount = members?.filter((m) => m.role === 'Owner').length ?? 0

  function handleInvite() {
    if (!inviteEmail.trim()) return
    setInviteSuccess(false)
    inviteMutation.mutate(
      { boardId, email: inviteEmail.trim(), role: inviteRole },
      {
        onSuccess: () => {
          setInviteEmail('')
          setInviteOpen(false)
          setInviteSuccess(true)
        },
      }
    )
  }

  function handleRoleChange(member: BoardMember, newRole: BoardRole) {
    changeRoleMutation.mutate({ boardId, userId: member.userId, role: newRole })
  }

  function handleRemove(userId: string) {
    removeMutation.mutate({ boardId, userId })
  }

  return (
    <div className={styles.root}>
      <div className={styles.header}>
        <span>Members</span>
        {isOwner && (
          <Button size="small" onClick={() => setInviteOpen((o) => !o)} aria-label="Invite member">
            Invite
          </Button>
        )}
      </div>

      {inviteSuccess && (
        <MessageBar intent="success" role="alert">
          <MessageBarBody>Invite sent successfully.</MessageBarBody>
        </MessageBar>
      )}

      {inviteMutation.isError && (
        <MessageBar intent="error" role="alert">
          <MessageBarBody>
            {inviteMutation.error?.code === 'member.already_member'
              ? 'This user is already a board member.'
              : 'Failed to send invite. Please try again.'}
          </MessageBarBody>
        </MessageBar>
      )}

      {isOwner && inviteOpen && (
        <div className={styles.inviteForm}>
          <Field label="Email">
            <Input
              type="email"
              value={inviteEmail}
              onChange={(_, d) => setInviteEmail(d.value)}
              placeholder="name@example.com"
              aria-label="Email"
            />
          </Field>
          <Field label="Role">
            <Select
              value={inviteRole}
              onChange={(_, d) => setInviteRole(d.value as BoardRole)}
              aria-label="role"
            >
              <option value="Owner">Owner</option>
              <option value="Member">Member</option>
              <option value="Viewer">Viewer</option>
            </Select>
          </Field>
          <div className={styles.inviteRow}>
            <Button appearance="primary" onClick={handleInvite} disabled={inviteMutation.isPending}>
              Send invite
            </Button>
            <Button onClick={() => setInviteOpen(false)}>Cancel</Button>
          </div>
        </div>
      )}

      {isPending && <Spinner role="progressbar" label="Loading members…" />}

      {!isPending && members && (
        <ul className={styles.list} aria-label="Board members">
          {members.map((member) => {
            const isLastOwner = member.role === 'Owner' && ownerCount <= 1
            return (
              <li key={member.userId} className={styles.item}>
                <span className={styles.name}>{member.displayName}</span>

                {isOwner ? (
                  <Select
                    value={member.role}
                    onChange={(_, d) => handleRoleChange(member, d.value as BoardRole)}
                    aria-label="role"
                    disabled={isLastOwner}
                  >
                    <option value="Owner">Owner</option>
                    <option value="Member">Member</option>
                    <option value="Viewer">Viewer</option>
                  </Select>
                ) : (
                  <span>{member.role}</span>
                )}

                {isOwner && !isLastOwner && (
                  <Button
                    size="small"
                    appearance="subtle"
                    onClick={() => handleRemove(member.userId)}
                    disabled={removeMutation.isPending}
                    aria-label={`Remove ${member.displayName}`}
