import { useState } from 'react'
import {
  Button,
  FluentProvider,
  Spinner,
  Title1,
  makeStyles,
  tokens,
  webLightTheme,
} from '@fluentui/react-components'
import { useParams } from 'react-router-dom'
import { useBoard } from '../hooks/useBoard'
import KanbanBoard from '../components/board/KanbanBoard'
import BoardMembersPanel from '../components/board/BoardMembersPanel'

const useStyles = makeStyles({
  root: {
    padding: tokens.spacingHorizontalXXL,
    overflowX: 'auto',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: tokens.spacingVerticalL,
  },
  membersPanel: {
    marginTop: tokens.spacingVerticalL,
  },
})

export default function BoardPage() {
  const styles = useStyles()
  const { boardId } = useParams<{ boardId: string }>()
  const { data: board, isPending } = useBoard(boardId ?? '')
  const [membersOpen, setMembersOpen] = useState(false)

  if (isPending) return <Spinner label="Loading board…" />

  if (!board) return null

  const isOwner = board.callerRole === 'Owner'

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <div className={styles.header}>
          <Title1 as="h1">{board.name}</Title1>
          {isOwner && (
            <Button onClick={() => setMembersOpen((o) => !o)} aria-label="Members">
              Members
            </Button>
          )}
        </div>

        {isOwner && membersOpen && (
          <div className={styles.membersPanel}>
            <BoardMembersPanel boardId={board.id} callerRole={board.callerRole} />
          </div>
        )}

        <KanbanBoard board={board} />
      </div>
    </FluentProvider>
  )
}

import { useQuery } from '@tanstack/react-query'

export interface BoardMember {
  userId: string
  displayName: string
  role: 'Owner' | 'Member' | 'Viewer'
  joinedAt: string
}

export interface ApiError {
  status: number
  code?: string
  title?: string
}

async function fetchBoardMembers(boardId: string): Promise<BoardMember[]> {
  const response = await fetch(`/api/v1/boards/${encodeURIComponent(boardId)}/members`)
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<BoardMember[]>
}

export function useBoardMembers(boardId: string) {
  return useQuery({
    queryKey: ['boards', boardId, 'members'],
    queryFn: () => fetchBoardMembers(boardId),
    enabled: Boolean(boardId),
  })
}

using Kanban.Api.Options;
using Kanban.Business.Interfaces;
using Kanban.Contracts;
using Microsoft.Extensions.Options;

namespace Kanban.Api.Endpoints;

public static class BoardMemberEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var members = routes.MapGroup("/boards/{boardId:guid}/members");

        members.MapGet("",
            async (Guid boardId, IBoardMembershipService membershipService) =>
                Results.Ok(await membershipService.ListMembersAsync(boardId)))
            .WithName("GetBoardMembers")
            .WithSummary("List members of a board")
            .Produces<IReadOnlyList<BoardMemberDto>>(200)
            .ProducesProblem(404)
            .RequireRateLimiting("authenticated");

        members.MapPost("/invite",
            async (
                Guid boardId,
                InviteBoardMemberRequest request,
                IBoardMembershipService membershipService,
                IOptions<CorsOptions> corsOptions) =>
            {
                var frontendBaseUrl = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? "http://localhost:5173";
                await membershipService.InviteAsync(boardId, request, frontendBaseUrl);
                return Results.Accepted();
            })
            .WithName("InviteBoardMember")
            .WithSummary("Invite a user to a board (Owner only)")
            .Produces(202)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(409)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        members.MapPatch("{userId:guid}/role",
            async (
                Guid boardId,
                Guid userId,
                ChangeMemberRoleRequest request,
                IBoardMembershipService membershipService) =>
                Results.Ok(await membershipService.ChangeRoleAsync(boardId, userId, request)))
            .WithName("ChangeMemberRole")
            .WithSummary("Change a member's board role (Owner only)")
            .Produces<BoardMemberDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        members.MapDelete("{userId:guid}",
            async (
                Guid boardId,
                Guid userId,
                IBoardMembershipService membershipService) =>
            {
                await membershipService.RemoveMemberAsync(boardId, userId);
                return Results.NoContent();
            })
            .WithName("RemoveBoardMember")
            .WithSummary("Remove a member from a board (Owner only)")
            .Produces(204)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");
    }
}

