using Kanban.Business.Interfaces;
using Kanban.Contracts;

namespace Kanban.Api.Endpoints;

public static class BoardMemberEndpoints
{
    public static void Map(IEndpointRouteBuilder routes)
    {
        var members = routes.MapGroup("/boards/{boardId:guid}/members");

        members.MapGet("",
            async (Guid boardId, IBoardMembershipService membershipService) =>
                Results.Ok(await membershipService.ListMembersAsync(boardId)))
            .WithName("GetBoardMembers")
            .WithSummary("List members of a board")
            .Produces<IReadOnlyList<BoardMemberDto>>(200)
            .ProducesProblem(404)
            .RequireRateLimiting("authenticated");

        members.MapPost("/invite",
            async (
                Guid boardId,
                InviteBoardMemberRequest request,
                IBoardMembershipService membershipService) =>
            {
                await membershipService.InviteAsync(boardId, request);
                return Results.Accepted();
            })
            .WithName("InviteBoardMember")
            .WithSummary("Invite a user to a board (Owner only)")
            .Produces(202)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(409)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        members.MapPatch("{userId:guid}/role",
            async (
                Guid boardId,
                Guid userId,
                ChangeMemberRoleRequest request,
                IBoardMembershipService membershipService) =>
                Results.Ok(await membershipService.ChangeRoleAsync(boardId, userId, request)))
            .WithName("ChangeMemberRole")
            .WithSummary("Change a member's board role (Owner only)")
            .Produces<BoardMemberDto>(200)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");

        members.MapDelete("{userId:guid}",
            async (
                Guid boardId,
                Guid userId,
                IBoardMembershipService membershipService) =>
            {
                await membershipService.RemoveMemberAsync(boardId, userId);
                return Results.NoContent();
            })
            .WithName("RemoveBoardMember")
            .WithSummary("Remove a member from a board (Owner only)")
            .Produces(204)
            .ProducesProblem(403)
            .ProducesProblem(404)
            .ProducesProblem(422)
            .RequireRateLimiting("mutating");
    }
}

using System.Data;
using System.Security.Claims;
using FluentValidation;
using Kanban.Business.Infrastructure;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Microsoft.Extensions.Logging;

namespace Kanban.Business.Services;

public sealed class AuthService : IAuthService
{
    private readonly IUserRepository _userRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<AuthService> _logger;

    public AuthService(
        IUserRepository userRepository,
        IAuthEventRepository authEventRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<AuthService> logger)
    {
        ArgumentNullException.ThrowIfNull(userRepository);
        ArgumentNullException.ThrowIfNull(authEventRepository);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _userRepository = userRepository;
        _authEventRepository = authEventRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<CurrentUserDto?> GetCurrentUserAsync(
        Guid userId,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("userId") }.ValidateAndThrow(userId);
        var user = await _userRepository.FindByIdAsync(userId);
        return user is null ? null : UserTransforms.ToDto(user);
    }

    public async Task HandleSignInAsync(
        string googleSub,
        string email,
        ClaimsIdentity claimsIdentity,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("googleSub") }.ValidateAndThrow(googleSub);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("email") }.ValidateAndThrow(email);
        ArgumentNullException.ThrowIfNull(claimsIdentity);

        await SqliteRetryPolicy.Pipeline.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var user = await _userRepository.FindByGoogleSubAsync(googleSub, tx);

                if (user is null)
                {
                    var userByEmail = await _userRepository.FindByEmailAsync(email, tx);
                    if (userByEmail is not null && userByEmail.GoogleSub is null)
                    {
                        await _userRepository.LinkGoogleSubAsync(userByEmail.Id, googleSub, tx);
                        userByEmail.LinkGoogleIdentity(googleSub);
                        user = userByEmail;
                    }
                }

                if (user is not null)
                {
                    claimsIdentity.AddClaim(new Claim("user_id", user.Id.ToString()));
                    claimsIdentity.AddClaim(new Claim("system_role",
                        user.SystemRole == SystemRole.Admin ? "admin" : "standard"));

                    var signedInAt = DateTimeOffset.UtcNow;
                    await _userRepository.UpdateLastSignInAsync(user.Id, signedInAt, tx);

                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: signedInAt,
                        EventType: AuthEventType.SignIn,
                        UserId: user.Id,
                        Outcome: "success");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogInformation(
                        "User {UserId} signed in with role {SystemRole}", user.Id, user.SystemRole);
                }
                else
                {
                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: DateTimeOffset.UtcNow,
                        EventType: AuthEventType.SignIn,
                        UserId: null,
                        Outcome: "unregistered");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogWarning("Unregistered Google user attempted sign-in");
                }

                tx.Commit();
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

