333	public sealed class TestAuthenticationHandler(
334	    IOptionsMonitor<TestAuthHandlerOptions> options,
335	    ILoggerFactory logger,
336	    UrlEncoder encoder)
337	    : AuthenticationHandler<TestAuthHandlerOptions>(options, logger, encoder)
338	{
339	    public const string SchemeName = "Test";
340	
341	    // ConcurrentDictionary is used instead of [ThreadStatic] because async request
342	    // processing can switch threads, making thread-local storage unreliable in tests.
343	    private static readonly ConcurrentDictionary<string, ClaimsPrincipal> _users = new();
344	
345	    public static string RegisterUser(ClaimsPrincipal user)
346	    {
347	        var token = Guid.NewGuid().ToString("N");
348	        _users[token] = user;
349	        return token;
350	    }
351	
352	    protected override Task<AuthenticateResult> HandleAuthenticateAsync()
353	    {
354	        if (!Request.Headers.TryGetValue("Authorization", out var authHeader))
355	            return Task.FromResult(AuthenticateResult.NoResult());
356	
357	        var headerValue = authHeader.ToString();
358	        var prefix = $"{SchemeName} ";
359	        if (!headerValue.StartsWith(prefix, StringComparison.Ordinal))
360	            return Task.FromResult(AuthenticateResult.NoResult());
361	
362	        var token = headerValue[prefix.Length..];
363	        if (!_users.TryGetValue(token, out var user))
364	            return Task.FromResult(AuthenticateResult.NoResult());
365	
366	        var ticket = new AuthenticationTicket(user, SchemeName);
367	        return Task.FromResult(AuthenticateResult.Success(ticket));
368	    }
369	}
