            {
                id = userId.ToString("D"),
                email,
                displayName = email,
                googleSub = $"google-sub-{userId:N}",
                registeredAt = DateTimeOffset.UtcNow.ToString("o"),
            });
        return userId;
    }

    public async Task<Guid> InsertBoardAsync(string name, Guid ownerUserId)
